import { useEffect, useState } from "react";

export default function AdminPanel() {
  const [submissions, setSubmissions] = useState([]);
  const [filter, setFilter] = useState("all");

  // Fetch all UTR submissions from your backend
  useEffect(() => {
    fetch("/api/admin/submissions", {
      headers: { Authorization: `Bearer ${localStorage.getItem("adminToken")}` }
    })
      .then(res => res.json())
      .then(setSubmissions);
  }, []);

  const handleAction = async (id, action) => {
    await fetch(`/api/admin/verify/${id}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.getItem("adminToken")}`
      },
      body: JSON.stringify({ status: action }) // "approved" or "rejected"
    });
    setSubmissions(prev =>
      prev.map(s => (s._id === id ? { ...s, status: action } : s))
    );
  };

  const filtered = filter === "all" ? submissions : submissions.filter(s => s.status === filter);

  return (
    <div>
      <h2>Payment Approvals</h2>
      {["all","pending","approved","rejected"].map(f => (
        <button key={f} onClick={() => setFilter(f)}>{f}</button>
      ))}
      <table>
        <thead><tr><th>Name</th><th>UTR</th><th>Status</th><th>Action</th></tr></thead>
        <tbody>
          {filtered.map(s => (
            <tr key={s._id}>
              <td>{s.name}</td>
              <td>{s.utr}</td>
              <td>{s.status}</td>
              <td>
                {s.status === "pending" && <>
                  <button onClick={() => handleAction(s._id, "approved")}>Approve</button>
                  <button onClick={() => handleAction(s._id, "rejected")}>Reject</button>
                </>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
